문 5. 다음 C 프로그램의 실행 결과는?
#include <stdio.h>
int main(void)
{
int i;
char buf[]="1234567890123456789012345";
char *str, ch;
str = buf;
for(i = 0; i <= 20; i += 4)
{
printf("%c ", *str++);
ch = *++str;
}
return 0;
}

